namespace InformationWeb.Controls.Graduation
{
    /// <summary>
    /// Danh sách văn bằng tốt nghiệp - lọc theo năm học và kỳ tốt nghiệp
    /// </summary>
    public partial class GraduationCerList : ControlBase
    {
        #region Const

        private const string PERMISSION_VIEW = "frmWebStudentList_View";
        private const string ADD_PAGE = "<br/><br/><br/><br/><br/><br/><br/><br/><br/><br/>";

        #endregion

        protected string strAddPage = "";
        private DataTable dtbData;

        #region Support Functions

        private void LoadExamDateList()
        {
            int? intYearID = WebGlobal.ToInt32(uYear.YearID);

            SIM_GraduationResult obj = new SIM_GraduationResult();
            DataTable dtbExamDate = obj.GetDataTable("SIM_ExamDate_SearchForGraduationCBX", "@YearID", intYearID);

            WebGlobal.InitDropDownList(ddlExamDateID, dtbExamDate, "ExamDateID", "ExamDateName", "--Tất cả--");
        }

        private void LoadData()
        {
            int? intYearID = WebGlobal.ToInt32(uYear.YearID);
            int? intExamDateID = WebGlobal.ValueFromDropBoxListInt32(ddlExamDateID);

            SIM_GraduationResult obj = new SIM_GraduationResult();
            dtbData = obj.GetDataTable("WEB_GraduationCerList_Search",
                "@YearID", intYearID,
                "@ExamDateID", intExamDateID);

            strAddPage = ADD_PAGE;
            if (dtbData != null)
            {
                if (dtbData.Rows.Count > 5)
                    strAddPage = "";

                gvData.DataSource = dtbData;
                gvData.DataBind();
                udpContent.Update();
            }
            else
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
            }
        }

        private bool IsValidData(bool isShowMsg)
        {
            if (uYear.YearID == null || uYear.YearID == "")
            {
                if (isShowMsg)
                    MsgBox.ShowWarning("Bạn phải chọn năm học!");

                return false;
            }

            return true;
        }

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            uYear.EditValueChanged += new InformationWeb.Controls.Sims.UYear.EditValueChangedDelegate(uYear_EditValueChanged);

            if (!IsPostBack)
            {
                if (User == null || !WebGlobal.HasPermission(PERMISSION_VIEW))
                {
                    MsgBox.ShowWarning("Bạn không có quyền truy cập chức năng này!");
                    this.Visible = false;
                    return;
                }

                LoadExamDateList();
            }
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (IsValidData(true))
                LoadData();
        }

        private void uYear_EditValueChanged(object yearID)
        {
            LoadExamDateList();
            udpSearch.Update();
        }
    }
}

