    /// <summary>
    /// Danh sách văn bằng tốt nghiệp - lọc theo năm học và kỳ tốt nghiệp
    /// </summary>
    public partial class GraduationCerList : ControlBase
    {
        #region Const

        private const string ADD_PAGE = "<br/><br/><br/><br/><br/><br/><br/><br/><br/><br/>";

        #endregion

        protected string strAddPage = "";
        private DataTable dtbData;

        #region Support Functions

        private void LoadYearList()
        {
            SIM_GraduationResult obj = new SIM_GraduationResult();
            DataTable dtbYear = obj.GetDataTable("SIM_Year_Search");
            WebGlobal.InitDropDownList(ddlYearID, dtbYear, BO.SIM_Year.C_YEARID, BO.SIM_Year.C_YEARNAME, "--Chọn--");
            ddlYearID.SelectedValue = WebGlobal.ValueForDropBoxList(SystemService.SYS_SettingService.GetStringValue("CurrentYearID"));
        }

        private void LoadExamDateList()
        {
            int? intYearID = WebGlobal.ToInt32(ddlYearID.SelectedValue);

            SIM_GraduationResult obj = new SIM_GraduationResult();
            DataTable dtbExamDate = obj.GetDataTable("SIM_ExamDate_SearchForGraduationCBX", "@YearID", intYearID);

            WebGlobal.InitDropDownList(ddlExamDateID, dtbExamDate, "ExamDateID", "ExamDateName", "--Tất cả--");
        }

        private DataTable GetSearchData()
        {
            int? intYearID = WebGlobal.ToInt32(ddlYearID.SelectedValue);
            int? intExamDateID = WebGlobal.ValueFromDropBoxListInt32(ddlExamDateID);

            SIM_GraduationResult obj = new SIM_GraduationResult();
            return obj.GetDataTable("WEB_GraduationCerList_Search",
                "@YearID", intYearID,
                "@ExamDateID", intExamDateID);
        }

        private void LoadData()
        {
            dtbData = GetSearchData();

            strAddPage = ADD_PAGE;
            if (dtbData != null)
            {
                if (dtbData.Rows.Count > 5)
                    strAddPage = "";

                gvData.DataSource = dtbData;
                gvData.DataBind();
                udpContent.Update();
            }
            else
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
            }
        }

        private bool IsValidData(bool isShowMsg)
        {
            if (ddlYearID.SelectedValue == null || ddlYearID.SelectedValue == "")
            {
                if (isShowMsg)
                    MsgBox.ShowWarning("Bạn phải chọn năm học!");

                return false;
            }

            return true;
        }

        private string GetExamDateTitle()
        {
            if (ddlExamDateID.SelectedIndex > 0)
                return ddlExamDateID.SelectedItem.Text;

            return String.Format("Năm học {0} - Tất cả kỳ tốt nghiệp", ddlYearID.SelectedItem.Text);
        }

        private string FormatDate(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value || objValue.ToString() == "")
                return "";

            DateTime dtmValue;
            if (DateTime.TryParse(objValue.ToString(), out dtmValue))
                return dtmValue.ToString("dd/MM/yyyy");

            return objValue.ToString();
        }

        private string HtmlCell(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value)
                return "";

            return HttpUtility.HtmlEncode(objValue.ToString());
        }

        private void ExportHtml(DataTable dtbExport, string strExamDateTitle)
        {
            StringBuilder sbHtml = new StringBuilder();
            int intRow;
            DataRow drw;

            sbHtml.Append("<!DOCTYPE html><html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8' />");
            sbHtml.Append("<title>DANH SÁCH VĂN BẰNG TỐT NGHIỆP</title>");
            sbHtml.Append("<style>");
            sbHtml.Append("body{font-family:Times New Roman,serif;font-size:13px;margin:20px;}");
            sbHtml.Append(".title{text-align:center;font-size:18px;font-weight:bold;text-transform:uppercase;margin-bottom:8px;}");
            sbHtml.Append(".subtitle{text-align:center;font-size:14px;font-weight:bold;margin-bottom:16px;}");
            sbHtml.Append("table{border-collapse:collapse;width:100%;}");
