            sbHtml.Append("th{text-align:center;font-weight:bold;background:#f0f0f0;}");
            sbHtml.Append(".center{text-align:center;}");
            sbHtml.Append(".left{text-align:left;}");
            sbHtml.Append("@media print{body{margin:10px;}}");
            sbHtml.Append("</style></head><body>");
            sbHtml.Append("<div class='title'>DANH SÁCH VĂN BẰNG TỐT NGHIỆP</div>");
            sbHtml.Append("<div class='subtitle'>");
            sbHtml.Append(HttpUtility.HtmlEncode(strExamDateTitle));
            sbHtml.Append("</div>");
            sbHtml.Append("<table><thead><tr>");
            sbHtml.Append("<th>STT</th>");
            sbHtml.Append("<th>Mã SV</th>");
            sbHtml.Append("<th>Họ đệm</th>");
            sbHtml.Append("<th>Tên</th>");
            sbHtml.Append("<th>Ngày sinh</th>");
            sbHtml.Append("<th>Lớp</th>");
            sbHtml.Append("<th>Khóa học</th>");
            sbHtml.Append("<th>Kỳ tốt nghiệp</th>");
            sbHtml.Append("<th>Số hiệu bằng</th>");
            sbHtml.Append("<th>Số vào sổ</th>");
            sbHtml.Append("<th>Ngày cấp bằng TN</th>");
            sbHtml.Append("<th>Số quyết định</th>");
            sbHtml.Append("<th>Ngày ký quyết định</th>");
            sbHtml.Append("<th>TBC toàn khóa</th>");
            sbHtml.Append("<th>Xếp loại toàn khóa</th>");
            sbHtml.Append("<th>Xếp loại tốt nghiệp</th>");
            sbHtml.Append("</tr></thead><tbody>");

            for (intRow = 0; intRow < dtbExport.Rows.Count; intRow++)
            {
                drw = dtbExport.Rows[intRow];
                sbHtml.Append("<tr>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append((intRow + 1).ToString());
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["StudentCode"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='left'>");
                sbHtml.Append(HtmlCell(drw["StudentFirstName"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='left'>");
                sbHtml.Append(HtmlCell(drw["StudentLastName"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["BirthDateText"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["ClassName"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='left'>");
                sbHtml.Append(HtmlCell(drw["CourseName"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='left'>");
                sbHtml.Append(HtmlCell(drw["ExamDateName"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["CerNo"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["SavedCerNo"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(FormatDate(drw["CerIssued"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["DecisionNo"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(FormatDate(drw["Signingdate"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["SummaryLearningMark"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["SummaryLearningLevel"]));
                sbHtml.Append("</td>");
                sbHtml.Append("<td class='center'>");
                sbHtml.Append(HtmlCell(drw["GraduationLevel"]));
                sbHtml.Append("</td>");
                sbHtml.Append("</tr>");
            }

            sbHtml.Append("</tbody></table>");
            sbHtml.Append("<script>window.onload=function(){window.print();};</script>");
            sbHtml.Append("</body></html>");

            Page.Response.Clear();
            Page.Response.Buffer = true;
            Page.Response.ContentType = "text/html";
            Page.Response.Charset = "utf-8";
            Page.Response.ContentEncoding = Encoding.UTF8;
            Page.Response.Write(sbHtml.ToString());
            Page.Response.End();
        }

        #endregion

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (User == null || WebGlobal.StudentID > 0)
                {
                    MsgBox.ShowWarning("Chức năng này dành cho cán bộ/giảng viên!");
                    this.Visible = false;
                    return;
                }

                LoadYearList();
                LoadExamDateList();
            }
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (IsValidData(true))
                LoadData();
        }

        protected void btnExport_Click(object sender, EventArgs e)
        {
            if (!IsValidData(true))
                return;

            DataTable dtbExport = GetSearchData();
            if (dtbExport == null)
            {
                MsgBox.ShowError("Việc lấy thông tin bị lỗi!");
                return;
            }

            if (dtbExport.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không có dữ liệu để xuất!");
                return;
            }

            ExportHtml(dtbExport, GetExamDateTitle());
        }

        protected void ddlYearID_SelectedIndexChanged(object sender, EventArgs e)
        {
            LoadExamDateList();
            udpSearch.Update();
        }
    }
}

