using System;
using System.Text;
using System.Web.UI;
using WebGlobal;

namespace InformationWeb.Pages.Graduation
{
    public partial class GraduationCerListExport : Page
    {
        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session[DCore.Globals.USER] == null)
            {
                Response.Redirect("~/dang-nhap.html");
                return;
            }

            if (WebGlobal.StudentID > 0)
            {
                Response.Redirect("~/");
                return;
            }

            string strKey = Request["key"];
            if (strKey == null || strKey.Trim() == "")
            {
                Response.Write("Không tìm thấy dữ liệu xuất.");
                return;
            }

            string strSessionKey = "GraduationCerListExport_" + strKey;
            object objHtml = Session[strSessionKey];
            if (objHtml == null)
            {
                Response.Write("Dữ liệu xuất đã hết hạn. Vui lòng xuất lại.");
                return;
            }

            Response.Clear();
            Response.ContentType = "text/html";
            Response.Charset = "utf-8";
            Response.ContentEncoding = Encoding.UTF8;
            Response.Write(objHtml.ToString());
            Session.Remove(strSessionKey);
            Response.End();
        }
    }
}

